alter table public.smoke_test_runs add column reviewed_version_id uuid,add foreign key(tenant_id,article_id,reviewed_version_id) references public.seo_article_versions(tenant_id,article_id,id);
create table public.provider_connections(tenant_id uuid not null references public.tenants(id),provider text not null check(provider in ('openai','ahrefs','moz','brave')),model text,license_acknowledged boolean not null default false,updated_at timestamptz not null default now(),created_at timestamptz not null default now(),primary key(tenant_id,provider));
alter table public.provider_connections enable row level security;
create policy provider_metadata_read on public.provider_connections for select to authenticated using(tenant_id=private.tenant_id() and (private.has_permission('settings.manage') or private.has_permission('articles.seo') or private.has_permission('publishers.research')));
revoke all on public.provider_connections from public,anon,authenticated;grant select on public.provider_connections to authenticated;grant all on public.provider_connections to service_role;
create table private.provider_credentials(tenant_id uuid not null,provider text not null,secret_id uuid not null,primary key(tenant_id,provider),foreign key(tenant_id,provider) references public.provider_connections(tenant_id,provider));
create table private.seo_usage(tenant_id uuid not null references public.tenants(id),day date not null,requests integer not null default 0,primary key(tenant_id,day));
create table private.signin_activity(session_id uuid primary key,user_id uuid not null references public.profiles(id),created_at timestamptz not null default now());
do $$ declare t text;begin foreach t in array array['provider_credentials','seo_usage','signin_activity'] loop execute format('alter table private.%I enable row level security',t);execute format('create policy service_only on private.%I for all to service_role using(true) with check(true)',t);execute format('revoke all on private.%I from public,anon,authenticated',t);execute format('grant all on private.%I to service_role',t);end loop;end $$;
create function public.store_provider_secret(p_actor uuid,p_provider text,p_secret text,p_model text,p_license boolean) returns void language plpgsql set search_path='' as $$ declare a public.profiles;s uuid;begin
 select * into a from public.profiles where id=p_actor and active and role='super_admin';if a.id is null then raise exception 'Owner permission required';end if;
 insert into public.provider_connections(tenant_id,provider,model,license_acknowledged) values(a.tenant_id,p_provider,p_model,p_license) on conflict(tenant_id,provider) do update set model=excluded.model,license_acknowledged=excluded.license_acknowledged,updated_at=clock_timestamp();
 select secret_id into s from private.provider_credentials where tenant_id=a.tenant_id and provider=p_provider;if s is null then select vault.create_secret(p_secret,'provider-'||a.tenant_id||'-'||p_provider) into s;insert into private.provider_credentials values(a.tenant_id,p_provider,s);else perform vault.update_secret(s,p_secret);end if;
end $$;
create function public.read_provider_secret(p_tenant uuid,p_provider text) returns jsonb language sql stable set search_path='' as $$ select jsonb_build_object('key',v.decrypted_secret,'model',p.model,'license_acknowledged',p.license_acknowledged) from public.provider_connections p join private.provider_credentials c on c.tenant_id=p.tenant_id and c.provider=p.provider join vault.decrypted_secrets v on v.id=c.secret_id where p.tenant_id=p_tenant and p.provider=p_provider $$;
create function public.revoke_provider_secret(p_actor uuid,p_provider text) returns void language plpgsql set search_path='' as $$ declare t uuid;s uuid;begin select tenant_id into t from public.profiles where id=p_actor and role='super_admin' and active;if t is null then raise exception 'Owner permission required';end if;select secret_id into s from private.provider_credentials where tenant_id=t and provider=p_provider;delete from private.provider_credentials where tenant_id=t and provider=p_provider;delete from vault.secrets where id=s;delete from public.provider_connections where tenant_id=t and provider=p_provider;end $$;
create function public.consume_seo_generation_quota(p_actor uuid,p_limit integer) returns boolean language plpgsql set search_path='' as $$ declare t uuid;n integer;begin select tenant_id into t from public.profiles where id=p_actor and active;if t is null or not private.actor_permission(p_actor,'articles.seo') then return false;end if;insert into private.seo_usage(tenant_id,day,requests) values(t,current_date,1) on conflict(tenant_id,day) do update set requests=private.seo_usage.requests+1 returning requests into n;return n<=greatest(1,least(100,p_limit));end $$;
create function public.record_signin_activity(p_actor uuid,p_session uuid) returns void language plpgsql set search_path='' as $$ declare t uuid;n integer;begin
 select tenant_id into t from public.profiles where id=p_actor and active;if t is null or not exists(select 1 from auth.sessions where id=p_session and user_id=p_actor) then return;end if;
 insert into private.signin_activity(session_id,user_id) values(p_session,p_actor) on conflict do nothing;get diagnostics n=row_count;if n=1 then insert into public.publishing_logs(tenant_id,actor_id,event_type,message) values(t,p_actor,'employee_signed_in','Account signed in to the publishing workspace.');end if;
end $$;
create function public.start_attributed_campaign(p_actor uuid,p_article uuid,p_version timestamptz,p_name text,p_sites uuid[],p_interval integer,p_start timestamptz,p_overrides jsonb,p_mode text,p_attribution jsonb) returns uuid language plpgsql set search_path='' as $$ declare c uuid;t uuid;assigned uuid;smoke public.smoke_test_runs;r public.articles;begin
 select tenant_id into t from public.profiles where id=p_actor and active;if not private.actor_permission(p_actor,'campaigns.launch') then raise exception 'Campaign launch permission required';end if;
 if nullif(p_attribution->>'smoke_run_id','') is not null then
 select * into smoke from public.smoke_test_runs where id=(p_attribution->>'smoke_run_id')::uuid and tenant_id=t and initiated_by=p_actor and status='awaiting_approval' and campaign_id is null for update;
 select * into r from public.articles where id=p_article and tenant_id=t for update;
 if smoke.id is null or smoke.article_id<>p_article or cardinality(p_sites)<>1 or p_sites[1]<>smoke.target_website_id or r.status<>'approved' or r.approved_version_id is distinct from smoke.reviewed_version_id or r.current_version_id is distinct from smoke.reviewed_version_id then raise exception 'Smoke test changed after preflight; run a fresh review';end if;
 end if;
 assigned:=nullif(p_attribution->>'assigned_to','')::uuid;if assigned is not null and not exists(select 1 from public.profiles where id=assigned and tenant_id=t and active) then raise exception 'Choose an active workspace employee';end if;
 c:=public.approve_and_create_campaign(p_actor,p_article,p_version,p_name,p_sites,p_interval,p_start,p_overrides,p_mode);update public.campaigns set assigned_to=assigned,client_name=left(coalesce(p_attribution->>'client_name',''),200),project_name=left(coalesce(p_attribution->>'project_name',''),200),report_recipient=left(coalesce(p_attribution->>'report_recipient',''),254) where id=c;if smoke.id is not null then update public.smoke_test_runs set campaign_id=c,status='scheduled' where id=smoke.id;end if;return c;
end $$;
-- Preserve exact reviewed version identity on every campaign path, including legacy callers.
alter function public.create_campaign(uuid,uuid,text,uuid[],integer,timestamptz,jsonb) rename to create_campaign_v4;
create function public.create_campaign(p_actor uuid,p_article uuid,p_name text,p_sites uuid[],p_interval integer,p_start timestamptz,p_overrides jsonb default '{}') returns uuid language plpgsql set search_path='' as $$ begin
 if not private.actor_permission(p_actor,'campaigns.launch') then raise exception 'Campaign launch permission required';end if;
 if not exists(select 1 from public.articles a join public.seo_article_versions v on v.id=a.approved_version_id and v.article_id=a.id where a.id=p_article and a.status='approved' and a.archived_at is null and v.status='approved' and a.current_version_id=a.approved_version_id and a.content=v.optimized_content and coalesce(v.seo_data->>'title','')=a.title and coalesce(v.seo_data->>'meta_title','')=a.meta_title and coalesce(v.seo_data->>'meta_description','')=a.meta_description and coalesce(v.seo_data->>'slug','')=a.slug and coalesce(v.seo_data->>'primary_keyword','')=a.focus_keyword and coalesce(v.seo_data->>'category','')=a.category and coalesce(v.seo_data->'tags','[]'::jsonb)=to_jsonb(a.tags)) then raise exception 'Approve the exact current article version before launching';end if;
 return public.create_campaign_v4(p_actor,p_article,p_name,p_sites,p_interval,p_start,p_overrides);end $$;
-- Replace legacy role-only gates with live permissions while keeping the established RPC bodies.
do $$ declare f record;d text;begin
 for f in select p.oid::regprocedure sig,p.proname name from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('reserve_connection_version','enqueue_browser_check','register_browser_worker','import_website_inventory') loop
  d:=pg_get_functiondef(f.sig);
  d:=replace(d,'a.role in (''admin'',''super_admin'',''seo_manager'')','private.actor_permission(a.id,''websites.connect'')');
  d:=replace(d,'a.role in (''super_admin'',''admin'',''seo_manager'')','private.actor_permission(a.id,''websites.connect'')');
  if f.name='register_browser_worker' then d:=replace(d,'role in (''admin'',''super_admin'')','private.actor_permission(id,''settings.manage'')');end if;
  if f.name='import_website_inventory' then d:=replace(d,'role in (''admin'',''super_admin'',''seo_manager'')','private.actor_permission(id,''websites.create'')');end if;
  execute d;
 end loop;
end $$;
-- Constrain legacy tenant metadata reads used by the original frontend.
alter policy tenant_read on public.import_batches using(tenant_id=private.tenant_id() and private.has_permission('websites.create'));
alter policy tenant_read on public.import_rows using(tenant_id=private.tenant_id() and private.has_permission('websites.create'));
alter policy tenant_read on public.website_metrics using(tenant_id=private.tenant_id() and (private.has_permission('publishers.research') or private.has_permission('websites.read')));
alter policy worker_tenant_read on public.browser_workers using(tenant_id=private.tenant_id() and (private.has_permission('settings.manage') or private.has_permission('campaigns.create') or private.has_permission('websites.connect')));
alter policy checks_tenant_read on public.connection_checks using(tenant_id=private.tenant_id() and private.has_permission('websites.connect'));
alter policy tenant_read on public.connection_permission_checks using(tenant_id=private.tenant_id() and private.has_permission('websites.connect'));
do $$ declare f record;begin for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('store_provider_secret','read_provider_secret','revoke_provider_secret','consume_seo_generation_quota','record_signin_activity','start_attributed_campaign','create_campaign','create_campaign_v4') loop execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;end $$;
